/**
 * Opening-time grid of the planner (design §5 F1), generated by rule from the local clock: stage 1
 * is now and every local quarter hour to the fine horizon; stage 2 adds the 5-minute marks around
 * each local peak of the stage-1 score curve.
 */
import { localParts } from "../time";
import type { EpochMs } from "../types";

const MINUTE_MS = 60_000;
/** Stage 1: every local quarter hour. */
export const GRID_STEP_MIN = 15;
/** Stage 2: the demand bucket's resolution. */
export const REFINE_STEP_MIN = 5;
/** Stage 2 reaches this far either side of a peak. */
export const REFINE_REACH_MIN = 10;

/**
 * Whole-minute instants in [from, to] whose local wall minute is a multiple of `stepMin`, ascending.
 * Steps actual instants, so a repeated fall-back hour gives both of its occurrences and a skipped
 * spring-forward hour gives none.
 */
export function localMarks(
	from: EpochMs,
	to: EpochMs,
	stepMin: number,
	timeZone: string,
): EpochMs[] {
	const marks: EpochMs[] = [];
	for (let t = Math.ceil(from / MINUTE_MS) * MINUTE_MS; t <= to; t += MINUTE_MS)
		if (localParts(t, timeZone).minuteOfDay % stepMin === 0) marks.push(t);
	return marks;
}

/** Stage 1: now, then every local quarter hour in (now, end). */
export function quarterHourGrid(
	now: EpochMs,
	end: EpochMs,
	timeZone: string,
): EpochMs[] {
	if (end <= now) return [now];
	return [now, ...localMarks(now + 1, end - 1, GRID_STEP_MIN, timeZone)];
}

/** Stage 2 around one peak: the local 5-minute marks within REFINE_REACH_MIN of it, inside [now, end), the peak excluded. */
export function refineMarks(
	peak: EpochMs,
	now: EpochMs,
	end: EpochMs,
	timeZone: string,
): EpochMs[] {
	const reach = REFINE_REACH_MIN * MINUTE_MS;
	return localMarks(
		Math.max(now, peak - reach),
		Math.min(end - 1, peak + reach),
		REFINE_STEP_MIN,
		timeZone,
	).filter((t) => t !== peak);
}

/**
 * Local peaks of a curve given in time order: points ranked strictly before each neighbour (rank 0 is
 * best; ranks are a total order, so a plateau of equal scores peaks once, at its best-ranked point).
 */
export function localPeaks<T>(
	curve: readonly T[],
	rankOf: (x: T) => number,
): T[] {
	return curve.filter((x, i) => {
		const r = rankOf(x);
		return (
			(i === 0 || r < rankOf(curve[i - 1])) &&
			(i === curve.length - 1 || r < rankOf(curve[i + 1]))
		);
	});
}
